'use client';

import { useState } from 'react';
import axios from 'axios';
// import styles from './Form.module.scss'; // Usando SCSS Modules

export default function AddressForm() {
  const [formData, setFormData] = useState({ name: '', ip: '', mask: '255.255.255.255' });
  const [generatedScript, setGeneratedScript] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const response = await axios.post(
        'http://localhost:3001/api/generate',
        { type: 'address', payload: formData },
        { withCredentials: true } // Importante para enviar o cookie httpOnly
      );
      setGeneratedScript(response.data.script);
    } catch (error) {
      console.error('Erro ao gerar script', error);
    }
  };

  return (
    // <div className={`card p-4 shadow-sm ${styles.fortiCard}`}>
    <div className="card p-4 shadow-sm">
      <h4 className="mb-3">Criar Objeto de Endereço</h4>
      <form onSubmit={handleSubmit}>
        <div className="mb-3">
          <label className="form-label">Nome do Objeto</label>
          <input type="text" className="form-control" required
            onChange={e => setFormData({...formData, name: e.target.value})} />
        </div>
        <div className="row mb-3">
          <div className="col">
            <label className="form-label">Endereço IP</label>
            <input type="text" className="form-control" placeholder="Ex: 192.168.1.50" required
              onChange={e => setFormData({...formData, ip: e.target.value})} />
          </div>
          <div className="col">
            <label className="form-label">Máscara Sub-rede</label>
            <input type="text" className="form-control" defaultValue="255.255.255.255" required
              onChange={e => setFormData({...formData, mask: e.target.value})} />
          </div>
        </div>
        <button type="submit" className="btn btn-primary w-100">Gerar Script CLI</button>
      </form>

      {generatedScript && (
        <div className="mt-4">
          <h5>Script Gerado (Copie e cole no meu terminal):</h5>
          <pre className="bg-dark text-success p-3 rounded">
            <code>{generatedScript}</code>
          </pre>
          <button className="btn btn-outline-secondary btn-sm" 
            onClick={() => navigator.clipboard.writeText(generatedScript)}>
            Copiar Script
          </button>
        </div>
      )}
    </div>
  );
}